export const regroupSettings={mode:'add',a:27,b:18,step:0};
export function regroupModel(mode,a,b){
 const at=Math.floor(a/10),ao=a%10,bt=Math.floor(b/10),bo=b%10;
 if(mode==='add'){const ones=ao+bo,tens=at+bt,exchange=ones>=10;return {at,ao,bt,bo,exchange,beforeTens:tens,beforeOnes:ones,workingTens:tens,workingOnes:ones,finalTens:tens+(exchange?1:0),finalOnes:ones%10,result:a+b};}
 const exchange=ao<bo;return {at,ao,bt,bo,exchange,beforeTens:at,beforeOnes:ao,workingTens:at-(exchange?1:0),workingOnes:ao+(exchange?10:0),finalTens:at-(exchange?1:0)-bt,finalOnes:ao+(exchange?10:0)-bo,result:a-b};
}
const slider=(key,label,min,max,n)=>`<label class="kid-range" for="regroup-${key}"><span>${label}</span><output id="regroup-out-${key}">${n}</output></label><input type="range" id="regroup-${key}" data-regroup-setting="${key}" min="${min}" max="${max}" value="${n}">`;
export function regroupControls(bi){const s=regroupSettings;return `<label class="kid-range" for="regroup-mode">${bi('Choose the operation','क्रिया चुनें')}</label><select id="regroup-mode"><option value="add" ${s.mode==='add'?'selected':''}>${bi('Addition · carry a ten','जोड़ · दहाई आगे ले जाएं')}</option><option value="subtract" ${s.mode==='subtract'?'selected':''}>${bi('Subtraction · unpack a ten','घटाव · दहाई खोलें')}</option></select>${slider('a',bi('Starting number','शुरुआती संख्या'),10,s.mode==='add'?49:99,s.a)}${slider('b',bi('Second number','दूसरी संख्या'),1,s.mode==='add'?49:s.a,s.b)}`;}
function blocks(label,tens,ones,bi,color='',removedTens=0,removedOnes=0){return `<div class="regroup-row ${color}"><strong>${label}</strong><div class="regroup-columns"><div><span>${bi('Tens','दहाई')} <b>${tens}</b></span><div class="regroup-rods">${Array.from({length:tens},()=>`<i class="regroup-rod">${'<em></em>'.repeat(10)}</i>`).join('')}${Array.from({length:removedTens},()=>'<i class="regroup-ghost-rod">×</i>').join('')}</div></div><div><span>${bi('Ones','इकाई')} <b>${ones}</b></span><div class="regroup-ones">${Array.from({length:ones},()=>'<i class="regroup-one"></i>').join('')}${Array.from({length:removedOnes},()=>'<i class="regroup-one removed">×</i>').join('')}</div></div></div></div>`;}
export function regroupScene(bi){const s=regroupSettings,m=regroupModel(s.mode,s.a,s.b),add=s.mode==='add',symbol=add?'+':'−';
 let caption='',explanation='',visual='';
 if(s.step===0){caption=bi('Build both numbers','दोनों संख्याएं बनाएं');explanation=bi(`Start with ${s.a}. ${add?'Add':'Take away'} ${s.b}. First notice the tens and ones.`,`${s.a} से शुरू करें। ${s.b} ${add?'जोड़ें':'घटाएं'}। पहले दहाई और इकाई देखें।`);visual=blocks(String(s.a),m.at,m.ao,bi)+`<div class="regroup-operation">${symbol}</div>`+blocks(String(s.b),m.bt,m.bo,bi,'green');}
 else if(add&&s.step===1){caption=bi('Join ones with ones, tens with tens','इकाई से इकाई, दहाई से दहाई जोड़ें');explanation=bi(`${m.ao} + ${m.bo} = ${m.beforeOnes} ones. ${m.at} + ${m.bt} = ${m.beforeTens} tens.`,`${m.ao} + ${m.bo} = ${m.beforeOnes} इकाई। ${m.at} + ${m.bt} = ${m.beforeTens} दहाई।`);visual=blocks(bi('All the blocks together','सभी ब्लॉक एक साथ'),m.beforeTens,m.beforeOnes,bi);}
 else if(add&&s.step===2){caption=m.exchange?bi('Trade ten ones for one ten','दस इकाइयों के बदले एक दहाई'):bi('No exchange needed this time','इस बार बदलने की जरूरत नहीं');explanation=m.exchange?bi(`The ${m.beforeOnes} ones become 1 ten and ${m.finalOnes} ones. Carry that ten to the tens column. The amount stays ${m.result}.`,`${m.beforeOnes} इकाई से 1 दहाई और ${m.finalOnes} इकाई बनती हैं। दहाई को दहाई वाले खाने में रखें। कुल मान ${m.result} ही रहता है।`):bi(`There are fewer than ten ones. Keep ${m.finalOnes} ones and ${m.finalTens} tens.`,`दस से कम इकाइयां हैं। ${m.finalOnes} इकाई और ${m.finalTens} दहाई रखें।`);visual=`<div class="exchange-rule">10 ${bi('ones','इकाई')} = 1 ${bi('ten','दहाई')}</div>`+blocks(bi('After regrouping','पुनर्समूहन के बाद'),m.finalTens,m.finalOnes,bi);}
 else if(!add&&s.step===1){caption=m.exchange?bi('Open one ten into ten ones','एक दहाई खोलकर दस इकाइयां बनाएं'):bi('There are enough ones already','इकाइयां पहले से पर्याप्त हैं');explanation=m.exchange?bi(`We need ${m.bo} ones but only ${m.ao} are loose. Open one ten. ${s.a} is now ${m.workingTens} tens and ${m.workingOnes} ones.`,`${m.bo} इकाई चाहिए लेकिन खुली इकाइयां ${m.ao} हैं। एक दहाई खोलें। ${s.a} अब ${m.workingTens} दहाई और ${m.workingOnes} इकाई है।`):bi(`We can take ${m.bo} ones from ${m.ao} ones without exchanging a ten.`,`बिना दहाई खोले ${m.ao} इकाई में से ${m.bo} इकाई हटा सकते हैं।`);visual=`<div class="exchange-rule">1 ${bi('ten','दहाई')} = 10 ${bi('ones','इकाई')}</div>`+blocks(bi('Still the starting amount','अभी भी शुरुआती मात्रा'),m.workingTens,m.workingOnes,bi);}
 else if(!add&&s.step===2){caption=bi('Take away the second number','दूसरी संख्या घटाएं');explanation=bi(`Remove ${m.bo} ones and ${m.bt} tens. The crossed blocks show what left. ${m.finalTens} tens and ${m.finalOnes} ones remain.`,`${m.bo} इकाई और ${m.bt} दहाई हटाएं। कटे ब्लॉक हटाई मात्रा दिखाते हैं। ${m.finalTens} दहाई और ${m.finalOnes} इकाई बचीं।`);visual=blocks(bi('What remains','क्या बचा'),m.finalTens,m.finalOnes,bi,'',m.bt,m.bo);}
 else{caption=bi('Read the number we made','बनी संख्या पढ़ें');explanation=bi(`${m.finalTens} tens and ${m.finalOnes} ones make ${m.result}. ${add?'Regrouping did not change the total.':'Exchanging did not change the starting value; taking blocks away changed it.'}`,`${m.finalTens} दहाई और ${m.finalOnes} इकाई से ${m.result} बनता है। ${add?'पुनर्समूहन से कुल मान नहीं बदला।':'बदलने से शुरुआती मान नहीं बदला; ब्लॉक हटाने से बदला।'}`);visual=blocks(bi('Our answer','हमारा उत्तर'),m.finalTens,m.finalOnes,bi,'green');}
 return `<section class="regroup-story"><div class="regroup-step-heading"><span>${bi('STEP','चरण')} ${s.step+1} / 4</span><h3>${caption}</h3></div><div class="regroup-board">${visual}</div><div class="regroup-explanation" role="status">${explanation}</div><div class="kid-equation">${s.a} ${symbol} ${s.b} ${s.step===3?'= '+m.result:'= ?'}</div><div class="regroup-stepper"><button class="kid-button light" id="regroup-back" ${s.step===0?'disabled':''}>${bi('Previous step','पिछला चरण')}</button><button class="kid-button" id="regroup-next">${s.step===3?bi('Replay the story','कहानी फिर चलाएं'):bi('Next step','अगला चरण')}</button></div><p class="scene-note">${bi('Change the numbers to try another story. The explanation will restart at the first step.','दूसरी कहानी के लिए संख्याएं बदलें। समझाना पहले चरण से फिर शुरू होगा।')}</p></section>`;
}
export function bindRegroup(bi){const s=regroupSettings;
 const update=()=>{document.querySelector('#play-scene').innerHTML=regroupScene(bi);bindButtons();};
 const bindButtons=()=>{document.querySelector('#regroup-back').onclick=()=>{s.step=Math.max(0,s.step-1);update();document.querySelector('#regroup-back').focus({preventScroll:true});};document.querySelector('#regroup-next').onclick=()=>{s.step=(s.step+1)%4;update();document.querySelector('#regroup-next').focus({preventScroll:true});};};
 document.querySelector('#regroup-mode').onchange=e=>{s.mode=e.target.value;s.a=s.mode==='add'?27:52;s.b=s.mode==='add'?18:27;s.step=0;document.querySelector('#play-controls>div').innerHTML=regroupControls(bi);bindRegroup(bi);update();};
 document.querySelectorAll('[data-regroup-setting]').forEach(input=>input.oninput=()=>{s[input.dataset.regroupSetting]=Number(input.value);if(s.mode==='subtract'&&s.b>s.a)s.b=s.a;document.querySelector('#regroup-b').max=s.mode==='add'?49:s.a;document.querySelector('#regroup-b').value=s.b;document.querySelector('#regroup-out-a').textContent=s.a;document.querySelector('#regroup-out-b').textContent=s.b;s.step=0;update();});bindButtons();
}
